-- dev-20260901-1225 网版主数据表（数据源：2026 所有网版内容登记表.xlsx）
-- 幂等：建表 IF NOT EXISTS；数据 INSERT IGNORE（screen_no 唯一键）

CREATE TABLE IF NOT EXISTS jjx_screen_master (
  screen_id BIGINT NOT NULL AUTO_INCREMENT COMMENT '网版ID',
  screen_no VARCHAR(30) NOT NULL COMMENT '网版编号（如 A0001）',
  frame_type VARCHAR(5) NOT NULL COMMENT '框型：A/B/C/F/G/H',
  content VARCHAR(1000) NULL COMMENT '网版内容记录',
  mesh VARCHAR(20) NULL COMMENT '目数（可选）',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态：1在用 0停用',
  remark VARCHAR(500) NULL COMMENT '备注',
  create_by VARCHAR(64) DEFAULT '' COMMENT '创建者',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by VARCHAR(64) DEFAULT '' COMMENT '更新者',
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (screen_id),
  UNIQUE KEY uk_screen_no (screen_no),
  KEY idx_frame_type (frame_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='网版主数据表';

